// Real-time local live HLS soak. Fixture media is generated by FFmpeg.
// No production origin, customer account or external URLs are involved.
import {chromium} from '@playwright/test';
import {createServer} from 'node:http';
import {readFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {performance} from 'node:perf_hooks';
import assert from 'node:assert/strict';
const seconds=Number(process.env.BLOFY_SOAK_SECONDS||1200);
assert.ok(Number.isInteger(seconds)&&seconds>=60&&seconds<=1200);
const root=resolve(process.argv[2]||'qa-soak');
const segments=readFileSync(resolve(root,'index.m3u8'),'utf8').split('\n').filter(v=>/^seg-[0-9]+\.ts$/.test(v));
assert.ok(segments.length*2>=seconds+20,'fixture must cover real duration plus startup margin');
const engine=readFileSync('node_modules/hls.js/dist/hls.min.js');
let began=0,requests=0,bytes=0;
const server=createServer((req,res)=>{
 const path=new URL(req.url,'http://localhost').pathname;
 res.setHeader('Cache-Control','no-store');
 if(path==='/'){res.setHeader('Content-Type','text/html');res.end('<video muted autoplay playsinline id="v"></video><script src="/hls.js"></script>');return}
 if(path==='/hls.js'){res.setHeader('Content-Type','application/javascript');res.end(engine);return}
 if(!began)began=performance.now();
 const latest=Math.min(segments.length,Math.floor((performance.now()-began)/2000)+4);
 const first=Math.max(0,latest-6);
 if(path==='/live.m3u8'){
  res.setHeader('Content-Type','application/vnd.apple.mpegurl');
  res.end('#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:2\n#EXT-X-MEDIA-SEQUENCE:'+first+'\n'+segments.slice(first,latest).map(s=>'#EXTINF:2.000,\n'+s+'\n').join(''));return
 }
 const name=path.slice(1);
 if(!/^seg-[0-9]+\.ts$/.test(name)||!segments.slice(first,latest).includes(name)||!existsSync(resolve(root,name))){res.writeHead(404).end();return}
 const data=readFileSync(resolve(root,name));requests++;bytes+=data.length;
 res.setHeader('Content-Type','video/mp2t');res.end(data)
});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
let browser;
try{
 browser=await chromium.launch({channel:'chrome',headless:true,args:['--autoplay-policy=no-user-gesture-required']});
 const page=await browser.newPage();const origin='http://127.0.0.1:'+server.address().port;
 await page.route('**/*',r=>r.request().url().startsWith(origin+'/')?r.continue():r.abort());
 await page.goto(origin);
 const result=await page.evaluate(async seconds=>{
  const v=document.getElementById('v'),h=new Hls({enableWorker:false,liveSyncDurationCount:3,maxLiveSyncPlaybackRate:1.1});
  const errors=[],pause=ms=>new Promise(r=>setTimeout(r,ms));
  h.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal)errors.push(e.details)});
  h.on(Hls.Events.MEDIA_ATTACHED,()=>h.loadSource('/live.m3u8'));
  h.on(Hls.Events.MANIFEST_PARSED,()=>v.play().catch(e=>errors.push(e.name)));
  h.attachMedia(v);
  const startup=performance.now();
  while(v.readyState<2||!v.videoWidth||v.getVideoPlaybackQuality().totalVideoFrames<2){
   if(errors.length||performance.now()-startup>20000)throw Error('startup_failed:'+errors.join(','));
   await pause(100)
  }
  const start=performance.now(),initial=v.getVideoPlaybackQuality().totalVideoFrames,initialTime=v.currentTime;
  let lastFrames=initial,lastAdvance=start,maxGap=0,samples=0;
  while(performance.now()-start<seconds*1000){
   await pause(500);
   const now=performance.now(),frames=v.getVideoPlaybackQuality().totalVideoFrames;
   if(errors.length||v.error||v.paused)throw Error('media_failed:'+errors.join(','));
   if(frames>lastFrames){maxGap=Math.max(maxGap,now-lastAdvance);lastAdvance=now;lastFrames=frames}
   if(now-lastAdvance>5000)throw Error('decoded_frames_stalled');
   samples++;
  }
  const result={elapsedSeconds:Math.floor((performance.now()-start)/1000),decodedFrames:lastFrames-initial,mediaProgressSeconds:Math.round(v.currentTime-initialTime),maxFrameProgressGapMs:Math.round(maxGap),samples,fatalErrors:errors.length};
  h.destroy();v.pause();return result
 },seconds);
 assert.ok(result.elapsedSeconds>=seconds);
 assert.ok(result.decodedFrames>=seconds*10);
 assert.ok(result.mediaProgressSeconds>=seconds-10);
 assert.ok(result.maxFrameProgressGapMs<=5000);
 assert.equal(result.fatalErrors,0);
 console.log('BLOFY_SYNTHETIC_LIVE_SOAK',JSON.stringify({...result,requests,bytes,scope:'local-generated-live-hls'}));
}finally{await browser?.close();await new Promise(r=>server.close(r))}
